#!/usr/bin/env python3
"""PTY harness to run the executable and capture screen output."""
import os, pty, sys, time, select, signal, subprocess

def run(args, keys=b"", env_extra=None, rows=24, cols=80, wait=1.0, post_wait=0.5, stdin_after=None):
    env = dict(os.environ)
    env["TERM"] = "xterm-256color"
    if env_extra:
        env.update(env_extra)
    master, slave = pty.openpty()
    # set window size
    import fcntl, termios, struct
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    p = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
    os.close(slave)
    out = b""
    def drain(dur):
        nonlocal out
        end = time.time() + dur
        while time.time() < end:
            r, _, _ = select.select([master], [], [], max(0, end - time.time()))
            if r:
                try:
                    data = os.read(master, 65536)
                except OSError:
                    break
                if not data:
                    break
                out += data
    drain(wait)
    if keys:
        os.write(master, keys)
        drain(post_wait)
    if stdin_after:
        for k, w in stdin_after:
            os.write(master, k)
            drain(w)
    try:
        p.terminate()
        p.wait(timeout=2)
    except Exception:
        p.kill()
    drain(0.3)
    os.close(master)
    return out

if __name__ == "__main__":
    # quick test
    out = run(sys.argv[1:])
    sys.stdout.buffer.write(out)

